import{f as c,D as l,o as a,c as u,a4 as d,b as i,w as t,a as r,G as n,a5 as s}from"./chunks/framework.6QvN0vQS.js";const f=JSON.parse('{"title":"GoodApps Cooperativas","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/07-estrategia-pruebas.md","filePath":"entregables-analisis-diseno/07-estrategia-pruebas.md","lastUpdated":null}'),p={name:"entregables-analisis-diseno/07-estrategia-pruebas.md"};function m(b,e,h,R,N,g){const o=l("Mermaid");return a(),u("div",null,[e[2]||(e[2]=d('<h1 id="goodapps-cooperativas" tabindex="-1">GoodApps Cooperativas <a class="header-anchor" href="#goodapps-cooperativas" aria-label="Permalink to &quot;GoodApps Cooperativas&quot;">​</a></h1><h2 id="estrategia-de-pruebas-y-plan-de-pruebas-de-rendimiento-y-seguridad" tabindex="-1">Estrategia de pruebas y plan de pruebas de rendimiento y seguridad <a class="header-anchor" href="#estrategia-de-pruebas-y-plan-de-pruebas-de-rendimiento-y-seguridad" aria-label="Permalink to &quot;Estrategia de pruebas y plan de pruebas de rendimiento y seguridad&quot;">​</a></h2><p><strong>Entregable de Análisis y Diseño Detallado — Artefactos 9.1 (Estrategia de pruebas) y 9.4 (Plan de pruebas de rendimiento y seguridad)</strong></p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Producto</td><td>GoodApps Cooperativas: plataforma de gestión en la nube (SaaS multi-tenant) para cooperativas de servicios públicos y sociales</td></tr><tr><td>Documento</td><td>Estrategia de pruebas, criterios de aceptación y plan de pruebas no funcionales</td></tr><tr><td>Destinatarios</td><td>Equipo de desarrollo, responsables de calidad y seguridad de la plataforma, responsables funcionales y usuarios clave de la cooperativa piloto, Laguna Larga (<code>LAG</code>, DEC-088)</td></tr><tr><td>Carácter</td><td>Documento derivado de la especificación vigente; no la reemplaza. Ante cualquier diferencia prevalecen la especificación maestra (<code>00</code>), sus anexos (en particular T08) y el registro de decisiones (<code>01</code>)</td></tr><tr><td>Versión</td><td>1.0</td></tr><tr><td>Fecha</td><td>05-11-2026</td></tr></tbody></table><blockquote><p><strong>Norma stack CoopApps (C-10, DEC-111–113, DEC-110).</strong> Los niveles, suites y trazabilidad RF→CP de este documento siguen vigentes. Donde se exija MongoDB/Redis/replica set o drivers Node, leer como <strong>redacción previa a DEC-111</strong>: la verificación en GoodApps usa <strong>integración contra Azure SQL</strong> (Testcontainers o entorno dedicado), <strong>Azure Queue</strong> donde aplique colas, <strong>Playwright</strong> en front React y contratos alineados a <code>18-openapi/</code>. No se reescriben masivamente los 5.710 CP; se alinea la estrategia y los nuevos CP nacen con la norma Azure. Impacto: <code>06-impacto-adaptacion-stack-goodapps.md</code> §12.3.</p></blockquote><h3 id="control-de-versiones" tabindex="-1">Control de versiones <a class="header-anchor" href="#control-de-versiones" aria-label="Permalink to &quot;Control de versiones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Versión</th><th>Fecha</th><th>Descripción del cambio</th><th>Autor</th></tr></thead><tbody><tr><td>1.0</td><td>05-11-2026</td><td>Versión inicial de la estrategia de pruebas (9.1) y del plan de pruebas de rendimiento y seguridad (9.4). Actualizada el mismo día por DEC-088 (cooperativa piloto: Laguna Larga), que reemplaza a DEC-081: se agregan los casos de aceptación de la migración de LAG</td><td></td></tr></tbody></table><h3 id="aprobaciones" tabindex="-1">Aprobaciones <a class="header-anchor" href="#aprobaciones" aria-label="Permalink to &quot;Aprobaciones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rol</th><th>Nombre</th><th>Firma</th><th>Fecha</th></tr></thead><tbody><tr><td>Elaboró</td><td></td><td></td><td></td></tr><tr><td>Revisó</td><td></td><td></td><td></td></tr><tr><td>Aprobó</td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="indice" tabindex="-1">Índice <a class="header-anchor" href="#indice" aria-label="Permalink to &quot;Índice&quot;">​</a></h2><ol><li>Propósito, alcance y fuentes</li><li>Objetivos de las pruebas</li><li>Principios</li><li>Niveles de prueba</li><li>Pruebas específicas del dominio</li><li>Plan de pruebas no funcionales (artefacto 9.4)</li><li>Pruebas de migración desde ProCoop</li><li>Datos de prueba</li><li>Ambientes de prueba</li><li>Automatización en integración continua</li><li>Criterios de entrada y salida por ola y definición de terminado</li><li>Gestión de defectos</li><li>Trazabilidad requisito → caso de prueba</li><li>Roles y responsabilidades</li><li>Casos de aceptación del piloto (Internet con datos sintéticos y migración de LAG)</li><li>Puntos a definir y observaciones sobre las fuentes</li></ol><hr><h2 id="_1-proposito-alcance-y-fuentes" tabindex="-1">1. Propósito, alcance y fuentes <a class="header-anchor" href="#_1-proposito-alcance-y-fuentes" aria-label="Permalink to &quot;1. Propósito, alcance y fuentes&quot;">​</a></h2><p>Este documento establece cómo se verifica que GoodApps Cooperativas cumple su especificación, desde la primera ola de construcción (O0) hasta el corte de ProCoop (O11). Ordena en una sola estrategia lo que la especificación ya exige de forma dispersa: la estrategia de pruebas obligatoria en CI de T08 §12, los criterios de aceptación y escenarios de la sección 17 de cada anexo, los criterios de salida de cada ola del plan <code>03</code> y la definición de terminado de la maestra §16.</p><p>Alcance: todas las aplicaciones (admin, PWA del socio, PWA de campo, landing, consola de plataforma), la API, los workers, las integraciones (T06) y la migración desde ProCoop (T07).</p><p>Fuentes utilizadas:</p><table tabindex="0"><thead><tr><th>Fuente</th><th>Contenido que se toma</th></tr></thead><tbody><tr><td><code>00-ESPECIFICACION-MAESTRA.md</code> §13, §14, §15, §16</td><td>Convenciones (pruebas de permisos negativos y de aislamiento obligatorias), resumen de RNF, olas e hitos, definición de terminado</td></tr><tr><td><code>anexos/T08-NFR-no-funcionales-seguridad.md</code> §7 a §14 y §17</td><td>RNF medibles con su criterio verificable, estrategia de pruebas en CI, escenarios ESC-01 a ESC-05 y criterios transversales por ola</td></tr><tr><td><code>anexos/T07-MIG-migracion-procoop.md</code> §9, §17</td><td>Conciliación, muestreo, corrida paralela y escenarios ESC-MIG</td></tr><tr><td><code>anexos/T01-PLA-plataforma-saas.md</code> §5.J, §7.10</td><td>Ambientes, juego canónico de datos, pipeline y matriz de verificación por entrega</td></tr><tr><td><code>03-plan-de-olas-y-prompts.md</code> §2, §4 a §15</td><td>Reglas R1–R20, scripts estándar, criterios de salida y pruebas extremo a extremo por ola</td></tr><tr><td>Anexos M01–M19, T01–T12, sección 17</td><td>Escenarios ESC-xxx y criterios de aceptación por requisito</td></tr><tr><td><code>04-matriz-trazabilidad.md</code> §15</td><td>Trazabilidad RF y RNF → prompt</td></tr></tbody></table><hr><h2 id="_2-objetivos-de-las-pruebas" tabindex="-1">2. Objetivos de las pruebas <a class="header-anchor" href="#_2-objetivos-de-las-pruebas" aria-label="Permalink to &quot;2. Objetivos de las pruebas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.º</th><th>Objetivo</th><th>Requisitos de referencia</th></tr></thead><tbody><tr><td>OBJ-1</td><td>Demostrar que cada requisito funcional cumple su criterio de aceptación (última columna de la tabla de RF de su anexo) con una prueba automatizada que cita su ID</td><td>Maestra §16; <code>03</code> R15, R16</td></tr><tr><td>OBJ-2</td><td>Garantizar el aislamiento entre cooperativas: ninguna ruta, job, archivo, evento ni caché expone datos de otro tenant</td><td>RNF-NFR-148, RNF-NFR-238; maestra §14</td></tr><tr><td>OBJ-3</td><td>Garantizar la exactitud monetaria: cero diferencias de centavos entre comprobante, cuenta corriente y contabilidad</td><td>RNF-NFR-200 a 209, RNF-NFR-229; maestra §14</td></tr><tr><td>OBJ-4</td><td>Asegurar que reintentos, interrupciones y duplicados no producen efectos repetidos</td><td>RNF-NFR-151, RNF-NFR-212 a 215</td></tr><tr><td>OBJ-5</td><td>Verificar las metas de rendimiento, capacidad, disponibilidad y recuperación sobre el perfil de referencia</td><td>T08 §7, §8; DEC-063; DEC-075</td></tr><tr><td>OBJ-6</td><td>Verificar los controles de seguridad (OWASP ASVS 5.0 nivel 2) y de privacidad (Ley 25.326)</td><td>T08 §9, §10</td></tr><tr><td>OBJ-7</td><td>Verificar la accesibilidad WCAG 2.2 AA y el funcionamiento sin conexión de la PWA de campo</td><td>RNF-NFR-180, RNF-NFR-186 a 191</td></tr><tr><td>OBJ-8</td><td>Demostrar que la migración desde ProCoop es repetible, conciliada y sin pérdida de saldos ni documentos</td><td>T07 §17; RNF-NFR-153, RNF-NFR-154</td></tr><tr><td>OBJ-9</td><td>Aprobar el recorrido completo del servicio Internet con datos sintéticos y obtener la aceptación formal de la cooperativa piloto, Laguna Larga (<code>LAG</code>), sobre su migración de electricidad, gas y prepago</td><td>DEC-005; DEC-088; T12 parte 1 §1.7; PA-MIG-17</td></tr><tr><td>OBJ-10</td><td>Bloquear la promoción a producción de toda versión sin evidencia completa</td><td>RF-NFR-022, RNF-NFR-165, RF-PLA-114</td></tr></tbody></table><hr><h2 id="_3-principios" tabindex="-1">3. Principios <a class="header-anchor" href="#_3-principios" aria-label="Permalink to &quot;3. Principios&quot;">​</a></h2><ol><li><strong>La prueba es parte del requisito.</strong> Ningún RF se considera implementado sin prueba automatizada que cite su ID en el nombre (<code>03</code> R15, R19).</li><li><strong>Pruebas contra infraestructura real.</strong> Las pruebas de integración usan MongoDB 7 en replica set, Redis y almacenamiento S3 compatible reales; está prohibido simular la base de datos en ellas (RNF-NFR-142).</li><li><strong>Suites que nunca se ponen en cuarentena.</strong> Aislamiento, permisos negativos e idempotencia no admiten excepciones por inestabilidad (RNF-NFR-162).</li><li><strong>Datos 100 % ficticios.</strong> Ningún dato real de socios, empleados ni de la DEMO de ProCoop se usa en repositorio, fixtures ni ambientes no productivos (RN-NFR-014, RNF-NFR-160).</li><li><strong>Metas internas medibles.</strong> Las metas numéricas de T08 son objetivos de ingeniería verificados en CI y en pruebas de carga; el compromiso contractual se deriva de ellas (T08 §5.2, CTR-NFR-01).</li><li><strong>Un fallo relevante impide promover.</strong> Los gates del pipeline son vinculantes (RNF-NFR-165, RF-PLA-114).</li></ol><hr><h2 id="_4-niveles-de-prueba" tabindex="-1">4. Niveles de prueba <a class="header-anchor" href="#_4-niveles-de-prueba" aria-label="Permalink to &quot;4. Niveles de prueba&quot;">​</a></h2><h3 id="_4-1-piramide-obligatoria" tabindex="-1">4.1 Pirámide obligatoria <a class="header-anchor" href="#_4-1-piramide-obligatoria" aria-label="Permalink to &quot;4.1 Pirámide obligatoria&quot;">​</a></h3><p>T08 fija qué se ejecuta en cada momento (RNF-NFR-140):</p><table tabindex="0"><thead><tr><th>Momento</th><th>Suites</th></tr></thead><tbody><tr><td>Cada PR</td><td>Unitarias, integración con Mongo y Redis reales, contrato, aislamiento multitenant, permisos negativos, seguridad estática y extremo a extremo de humo</td></tr><tr><td>Nocturno</td><td>Extremo a extremo completo, fuzzing desde OpenAPI, DAST de línea base, accesibilidad, propiedades con ≥ 10.000 casos</td></tr><tr><td>Semanal o por ola</td><td>Carga, resistencia, caos, restauración, mutación</td></tr></tbody></table><h3 id="_4-2-detalle-por-nivel" tabindex="-1">4.2 Detalle por nivel <a class="header-anchor" href="#_4-2-detalle-por-nivel" aria-label="Permalink to &quot;4.2 Detalle por nivel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nivel</th><th>Qué verifica</th><th>Herramientas (según fuentes)</th><th>Meta o criterio</th><th>Requisitos</th></tr></thead><tbody><tr><td>Unitarias</td><td>Lógica pura en <code>lib/</code> y <code>packages/shared</code> (dinero, fechas, cálculo tarifario, fiscal, imputación, mora) sin red</td><td><code>node --test</code> y c8 en backend; Vitest y Vue Test Utils en front y paquetes</td><td>Suite completa ≤ 5 min; cobertura global líneas ≥ 80 % y ramas ≥ 70 %; módulos críticos líneas ≥ 95 % y ramas ≥ 90 %; líneas modificadas en el PR ≥ 85 %</td><td>RNF-NFR-141, RNF-NFR-158</td></tr><tr><td>Integración por módulo</td><td>Repositorios, servicios, transacciones, índices únicos, plugin de tenancy, outbox, jobs</td><td>Supertest; MongoDB 7 en replica set, Redis y S3 compatible en contenedor; antivirus en contenedor</td><td>100 % de repositorios y servicios con pruebas de integración; 0 simulaciones del driver en <code>*.int.test.js</code></td><td>RNF-NFR-142; <code>03</code> R15</td></tr><tr><td>Contrato de API</td><td>OpenAPI generado desde los esquemas Zod; diff semántico de cambios incompatibles; importes como cadena decimal</td><td><code>zod-to-openapi</code> o equivalente; linter de OpenAPI</td><td>0 cambios incompatibles no versionados; 0 importes numéricos en OpenAPI</td><td>RNF-NFR-143, RNF-NFR-175, RNF-NFR-201, RNF-NFR-247</td></tr><tr><td>Contrato de eventos</td><td>Esquemas de eventos validados por productor y consumidor, con <code>schemaVersion</code></td><td>Gate de diff de esquemas de eventos</td><td>0 consumidores rotos por un cambio de evento</td><td>RNF-NFR-143, RNF-NFR-178</td></tr><tr><td>Contrato de conectores</td><td>Conectores de T06 contra contratos grabados del proveedor y, en nocturno, contra homologación o sandbox (ARCA homologación, pasarelas en modo prueba)</td><td>Simulador de conectores (RF-INT-031)</td><td>0 rechazos por codificación en archivos de intercambio</td><td>RNF-NFR-143, RNF-NFR-198</td></tr><tr><td>Extremo a extremo</td><td>Recorridos críticos por ola en admin y PWA</td><td>Playwright en Chromium, Firefox y WebKit más emulación móvil (Android de gama baja e iPhone)</td><td>Humo ≤ 10 min por PR; completo nocturno con éxito ≥ 99 % sin reintentos; recorrido del piloto Internet (escenario 37 de BASE §34) obligatorio desde O6</td><td>RNF-NFR-144</td></tr><tr><td>Aceptación de usuario</td><td>Recorridos de negocio ejecutados por usuarios clave de la cooperativa piloto en <code>staging</code> o <code>sandbox</code>, sobre los escenarios de la sección 17 de cada anexo; cierre con acta</td><td>Ambiente <code>sandbox</code> con tenant gemelo (RF-PLA-111)</td><td>Criterios de salida de la ola cumplidos y acta de aceptación firmada (AGR §7 etapa F)</td><td><code>03</code> §4 a §15; T07 RF-MIG-087</td></tr><tr><td>Regresión</td><td>Conjuntos dorados de cálculo tarifario, fiscal y de mora; reproducción de liquidaciones históricas; comparación línea base de rendimiento</td><td>Suite de conjuntos dorados; job de comparación (T07); resultados k6 en <code>qualityEvidence</code></td><td>0 diferencias no explicadas; regresión de rendimiento &gt; 20 % bloquea la liberación</td><td>RNF-NFR-153, RNF-NFR-179, RNF-NFR-145</td></tr></tbody></table><h3 id="_4-3-suites-transversales-obligatorias" tabindex="-1">4.3 Suites transversales obligatorias <a class="header-anchor" href="#_4-3-suites-transversales-obligatorias" aria-label="Permalink to &quot;4.3 Suites transversales obligatorias&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Suite</th><th>Alcance</th><th>Meta</th><th>Requisitos</th></tr></thead><tbody><tr><td>Aislamiento multitenant</td><td>Recorre el registro de rutas (<code>admin</code>, socio, <code>platform</code>, <code>public</code>, <code>ext</code>) con datos en TEN-001 y TEN-002 con el mismo código interno; incluye webhooks, sincronización offline, URLs firmadas, eventos, jobs, cachés, colas, notificaciones push, logs y métricas</td><td>100 % de rutas y jobs cubiertos; 0 fugas; una ruta nueva sin caso hace fallar el build</td><td>RNF-NFR-148, RNF-NFR-238; <code>npm run test:isolation</code></td></tr><tr><td>Permisos negativos</td><td>Generada desde el catálogo de capabilities (T02): sin capability → 403 sin efectos; con capability fuera de alcance → sin efectos</td><td>100 % de capabilities con caso negativo</td><td>RNF-NFR-150</td></tr><tr><td>Idempotencia e interrupción</td><td>Falla a mitad y reintento, doble <code>Idempotency-Key</code>, doble webhook</td><td>100 % de jobs y rutas económicas</td><td>RNF-NFR-151</td></tr><tr><td>Propiedades</td><td><code>money</code>, prorrateos, intereses, redondeos y fechas de negocio</td><td>≥ 10.000 casos por propiedad en nocturno</td><td>RNF-NFR-152</td></tr><tr><td>Mutación</td><td><code>money</code>, motor tarifario, fiscal, imputación</td><td>Puntaje ≥ 70 % semanal</td><td>RNF-NFR-159</td></tr></tbody></table><hr><h2 id="_5-pruebas-especificas-del-dominio" tabindex="-1">5. Pruebas específicas del dominio <a class="header-anchor" href="#_5-pruebas-especificas-del-dominio" aria-label="Permalink to &quot;5. Pruebas específicas del dominio&quot;">​</a></h2><h3 id="_5-1-calculo-tarifario-y-exactitud-monetaria-con-decimal128" tabindex="-1">5.1 Cálculo tarifario y exactitud monetaria con Decimal128 <a class="header-anchor" href="#_5-1-calculo-tarifario-y-exactitud-monetaria-con-decimal128" aria-label="Permalink to &quot;5.1 Cálculo tarifario y exactitud monetaria con Decimal128&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Qué se prueba</th><th>Cómo</th><th>Meta</th><th>Requisitos y escenarios</th></tr></thead><tbody><tr><td>Uso exclusivo de <code>Decimal128</code>/<code>decimal.js</code></td><td>Regla SAST/ESLint que detecta aritmética, <code>parseFloat</code>, <code>toFixed</code> o <code>Math.round</code> sobre campos monetarios fuera de <code>packages/shared/money</code></td><td>0 hallazgos al fusionar</td><td>RN-NFR-005, RNF-NFR-200, RNF-NFR-206</td></tr><tr><td>Precisión y redondeo por concepto</td><td>Validación de catálogo; conjunto dorado fiscal</td><td>Precisión declarada para el 100 % de los conceptos; 0 rechazos ARCA por redondeo</td><td>RNF-NFR-202, RNF-NFR-203</td></tr><tr><td>Suma de partes igual al total</td><td>Propiedades con fast-check: &quot;no se crea ni se pierde un centavo&quot;, resultado independiente del orden y del huso horario del servidor</td><td>10.000 casos por propiedad</td><td>RN-NFR-006, RNF-NFR-152, RNF-NFR-204; escenario 72 de BASE §34</td></tr><tr><td>Reproducibilidad</td><td>Reejecutar una liquidación de 24 meses atrás con la versión de tarifa y reglas aplicada en su momento</td><td>Resultado idéntico al original</td><td>RNF-NFR-179, RNF-NFR-223; escenario 5 de BASE §34</td></tr><tr><td>Simulación sin efectos</td><td>Contar escrituras en colecciones productivas durante una simulación tarifaria</td><td>0 escrituras</td><td>RNF-NFR-223; escenarios 39 y 73 de BASE §34</td></tr><tr><td>Período parcialmente procesado</td><td>Lote con cambio tarifario a mitad; reejecución</td><td>Mantiene universo y versiones; no reescribe documentos</td><td>ESC-05 (T08 §17.1); RNF-NFR-215</td></tr><tr><td>Cálculo del piloto</td><td>Primer comprobante de Internet con abono, promoción e instalación</td><td>Resultado del ejemplo de M04 §9.3.9 (ver observación OBS-01 en la sección 16)</td><td>ESC-TAR-03 (M04); ESC-SRV-INT-01 (T12 parte 1)</td></tr><tr><td>Intereses y recargos por días</td><td>Conjunto dorado de fin de mes y año bisiesto</td><td>En verde</td><td>RNF-NFR-208</td></tr></tbody></table><h3 id="_5-2-numeracion-fiscal" tabindex="-1">5.2 Numeración fiscal <a class="header-anchor" href="#_5-2-numeracion-fiscal" aria-label="Permalink to &quot;5.2 Numeración fiscal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Qué se prueba</th><th>Cómo</th><th>Meta</th><th>Requisitos y escenarios</th></tr></thead><tbody><tr><td>Correlatividad sin huecos ni duplicados por punto de venta y tipo</td><td>10.000 emisiones con fallos inyectados, contra homologación y simulador</td><td>0 huecos y 0 duplicados</td><td>RNF-NFR-217</td></tr><tr><td>Resultado incierto ante timeout</td><td>Conector que confirma después del timeout; consulta del último autorizado antes de reintentar</td><td>0 reintentos ciegos; 0 duplicados</td><td>RNF-NFR-011, RNF-NFR-221; M06 §17.4 escenario 32</td></tr><tr><td>Reintento fiscal sin duplicar retenciones</td><td>Reintento de una emisión con retenciones</td><td>Sin duplicados</td><td>RNF-NFR-212; escenario 50 de BASE §34</td></tr><tr><td>Observaciones de ARCA</td><td>Autorización con observaciones</td><td>No se reemite</td><td>Escenario 61 de BASE §34</td></tr><tr><td>Restauración posterior a emisiones</td><td>Restaurar a un punto anterior a una emisión confirmada</td><td>Se concilia con ARCA antes de reanudar; no se reemite ni se renumera</td><td>RNF-NFR-044; ESC-04; M06 §17.5</td></tr><tr><td>Continuidad al corte de ProCoop</td><td>Último número autorizado consultado a ARCA al corte</td><td>Prevalece ARCA si difiere de ProCoop</td><td>RN-MIG-028; PA-MIG-08 (asumida, DEC-072)</td></tr></tbody></table><h3 id="_5-3-idempotencia" tabindex="-1">5.3 Idempotencia <a class="header-anchor" href="#_5-3-idempotencia" aria-label="Permalink to &quot;5.3 Idempotencia&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Qué se prueba</th><th>Meta</th><th>Requisitos y escenarios</th></tr></thead><tbody><tr><td><code>Idempotency-Key</code> obligatorio en todo <code>POST</code>/<code>PATCH</code> económico o de integración: mismo cuerpo → misma respuesta; cuerpo distinto → 422; en curso → 409; sin clave → 400</td><td>100 % de rutas económicas</td><td>RNF-NFR-212</td></tr><tr><td>Claves naturales únicas como segunda barrera (obligaciones del ciclo, pagos externos, comprobantes, series de equipos, turnos, mutaciones offline)</td><td>Inserción duplicada rechazada en el 100 % de las pruebas</td><td>RNF-NFR-213</td></tr><tr><td>Webhooks y archivos de rendición deduplicados</td><td>Reprocesar dos veces el mismo archivo: 0 cobros nuevos; webhook triplicado: un cobro</td><td>RNF-NFR-018, RNF-NFR-218; ESC-COB-R01 (M07)</td></tr><tr><td>Jobs reanudables con checkpoint</td><td><code>kill -9</code> del worker durante un lote: mismo resultado que sin caída (hash de documentos)</td><td>RNF-NFR-013, RNF-NFR-215; escenarios 6 y 59 de BASE §34</td></tr><tr><td>Doble clic en la UI</td><td>Doble clic en &quot;Cobrar&quot;: un recibo</td><td>RNF-NFR-226</td></tr><tr><td>Exclusión mutua de lotes</td><td>Dos lanzamientos simultáneos del mismo lote: uno se ejecuta y otro se rechaza</td><td>RNF-NFR-216</td></tr></tbody></table><h3 id="_5-4-aislamiento-multitenant" tabindex="-1">5.4 Aislamiento multitenant <a class="header-anchor" href="#_5-4-aislamiento-multitenant" aria-label="Permalink to &quot;5.4 Aislamiento multitenant&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Qué se prueba</th><th>Meta</th><th>Requisitos y escenarios</th></tr></thead><tbody><tr><td>Suite genérica de aislamiento por ruta y job (sección 4.3)</td><td>100 % cubierto; 0 fugas</td><td>RNF-NFR-148; escenarios 16, 19, 21, 29, 43, 45, 86 de BASE §34</td></tr><tr><td>Plugin de tenancy: consulta, <code>aggregate</code>, <code>update</code>, <code>delete</code>, <code>bulkWrite</code>, <code>$lookup</code>, <code>$unionWith</code>, <code>$graphLookup</code> sin <code>tenantId</code> lanzan error; prueba de mutación del plugin</td><td>0 consultas sin tenant; deshabilitar el plugin rompe la suite</td><td>RNF-NFR-149, RNF-NFR-238</td></tr><tr><td>Índices compuestos que empiezan por <code>tenantId</code></td><td>0 índices fuera de convención (script <code>check-indexes</code>)</td><td>RNF-NFR-025, RNF-NFR-149</td></tr><tr><td>Aislamiento criptográfico: un valor cifrado de TEN-001 copiado a TEN-002 no descifra</td><td>Falla al descifrar</td><td>RNF-NFR-056</td></tr><tr><td>Escenarios del piloto y de módulos</td><td>404 sin revelar existencia</td><td>ESC-SRV-INT-06 (T12), ESC-TEC-25 (M10), ESC-COB-T01 (M07), M06 §17.3 escenarios 27 a 29</td></tr></tbody></table><h3 id="_5-5-outbox-y-eventos" tabindex="-1">5.5 Outbox y eventos <a class="header-anchor" href="#_5-5-outbox-y-eventos" aria-label="Permalink to &quot;5.5 Outbox y eventos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Qué se prueba</th><th>Meta</th><th>Requisitos</th></tr></thead><tbody><tr><td>Auditoría y evento de outbox en la misma transacción que el cambio</td><td>Verificado en prueba de integración de escritura</td><td>RN-NFR-020, RNF-NFR-004</td></tr><tr><td>Atomicidad: falla forzada después de crear el recibo y antes del outbox</td><td>La base queda sin cambios</td><td>M07 §17.1 criterio 3; RNF-NFR-211</td></tr><tr><td>Latencia de publicación</td><td>p95 ≤ 5 s y p99 ≤ 30 s; alerta si el pendiente más antiguo supera 60 s (prueba con 10.000 eventos)</td><td>RNF-NFR-014</td></tr><tr><td>Consumidores idempotentes (<code>inboxReceipts</code>)</td><td>Entregar tres veces el mismo evento produce un solo efecto</td><td>RNF-NFR-214</td></tr><tr><td>Pérdida total de Redis</td><td>Recuperación de colas ≤ 15 min reencolando desde Mongo, sin duplicar efectos</td><td>RNF-NFR-041</td></tr><tr><td>Cargas de migración silenciosas</td><td>Una carga en modo <code>migration</code> no envía correos ni SMS ni publica deuda a entes</td><td>RF-MIG-040, RN-MIG-043</td></tr></tbody></table><h3 id="_5-6-funcionamiento-sin-conexion-de-la-pwa-de-campo" tabindex="-1">5.6 Funcionamiento sin conexión de la PWA de campo <a class="header-anchor" href="#_5-6-funcionamiento-sin-conexion-de-la-pwa-de-campo" aria-label="Permalink to &quot;5.6 Funcionamiento sin conexión de la PWA de campo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Qué se prueba</th><th>Meta</th><th>Requisitos y escenarios</th></tr></thead><tbody><tr><td>App shell disponible sin red; datos de <code>/api</code> no cacheados por HTTP</td><td>Prueba Playwright sin conexión</td><td>RNF-NFR-186</td></tr><tr><td>Motor único de cola en IndexedDB con <code>clientMutationId</code></td><td>Una sola implementación; 0 usos de <code>localStorage</code> para datos de negocio</td><td>RNF-NFR-187</td></tr><tr><td>Sincronización idempotente</td><td>Lote de 200 mutaciones ≤ 10 s p95; tres reintentos del mismo lote producen un solo efecto</td><td>RNF-NFR-017, RNF-NFR-219; ESC-TEC-09</td></tr><tr><td>Capacidad sin conexión</td><td>≥ 7 días, ≥ 1.000 tareas y ≥ 300 fotos en dispositivo de referencia</td><td>RNF-NFR-188</td></tr><tr><td>Conflicto de sincronización</td><td>Se conserva la evidencia, se abre el conflicto, no se duplica salida de equipo ni activación</td><td>RNF-NFR-190; ESC-03 (T08) / ESC-TEC-08 (M10); escenario 70 de BASE §34</td></tr><tr><td>Red intermitente y cierre de la app con cola pendiente</td><td>Casos en verde</td><td>RNF-NFR-156</td></tr><tr><td>Seguridad de datos locales</td><td>0 datos de tareas no asignadas en el dispositivo (inspección de IndexedDB)</td><td>RNF-NFR-189 (A validar, PA-NFR-14)</td></tr><tr><td>Operaciones que no se encolan (login, cobros, anulaciones, configuración)</td><td>Botones deshabilitados sin red</td><td>RNF-NFR-191</td></tr><tr><td>Actualización de la PWA con cola pendiente</td><td>Un técnico con 20 operaciones en cola actualiza y sincroniza sin pérdida</td><td>RF-PLA-150, RNF-NFR-174</td></tr></tbody></table><hr><h2 id="_6-plan-de-pruebas-no-funcionales-artefacto-9-4" tabindex="-1">6. Plan de pruebas no funcionales (artefacto 9.4) <a class="header-anchor" href="#_6-plan-de-pruebas-no-funcionales-artefacto-9-4" aria-label="Permalink to &quot;6. Plan de pruebas no funcionales (artefacto 9.4)&quot;">​</a></h2><h3 id="_6-1-perfil-de-carga-de-referencia" tabindex="-1">6.1 Perfil de carga de referencia <a class="header-anchor" href="#_6-1-perfil-de-carga-de-referencia" aria-label="Permalink to &quot;6.1 Perfil de carga de referencia&quot;">​</a></h3><p>Las pruebas de rendimiento usan el perfil de referencia de T08 §7.1 (adoptado por DEC-075): tenant estándar de 25.000 suministros y tenant grande de 150.000, con diseño para 100 tenants y escala hasta 300 sin rediseño. El dataset sintético de tenant grande (150.000 suministros y 5 años de movimientos) se genera con <code>seed:carga --perfil=grande</code> y existe solo en <code>staging</code> (T08 §18). El perfil se recalibra con las mediciones de la cooperativa piloto, LAG (AGR-020; DEC-088), tomadas en el perfilado de su migración.</p><h3 id="_6-2-rendimiento-interactivo" tabindex="-1">6.2 Rendimiento interactivo <a class="header-anchor" href="#_6-2-rendimiento-interactivo" aria-label="Permalink to &quot;6.2 Rendimiento interactivo&quot;">​</a></h3><p>Herramienta: k6 (RNF-NFR-145), medición en servidor al 100 % de la carga pico.</p><table tabindex="0"><thead><tr><th>Escenario k6</th><th>Requisito</th><th>Meta</th></tr></thead><tbody><tr><td><code>read-by-id</code></td><td>RNF-NFR-001</td><td>p95 ≤ 200 ms; p99 ≤ 500 ms</td></tr><tr><td><code>list-paginated</code></td><td>RNF-NFR-002</td><td>p95 ≤ 400 ms; p99 ≤ 1 s; <code>size</code> máximo 100</td></tr><tr><td><code>search</code></td><td>RNF-NFR-003</td><td>p95 ≤ 500 ms en tenant grande; sin <code>COLLSCAN</code></td></tr><tr><td><code>write-simple</code></td><td>RNF-NFR-004</td><td>p95 ≤ 500 ms; p99 ≤ 1,2 s</td></tr><tr><td><code>cash-payment</code> (30 cajas concurrentes por tenant grande)</td><td>RNF-NFR-005, RNF-NFR-224</td><td>p95 ≤ 800 ms; recibo listo para imprimir ≤ 2 s medido en cliente (DEC-063 fija p95 interactivo ≤ 800 ms)</td></tr><tr><td><code>account-360</code></td><td>RNF-NFR-006</td><td>p95 ≤ 1 s</td></tr><tr><td><code>dashboards</code></td><td>RNF-NFR-007</td><td>Tableros p95 ≤ 2 s; reportes sincrónicos ≤ 5 s; exportación de más de 10.000 filas siempre asíncrona</td></tr><tr><td><code>bi-extract</code> en paralelo con <code>cash-payment</code></td><td>RNF-NFR-019</td><td>p95 ≤ 800 ms por página; se mantienen las metas de RNF-NFR-005</td></tr><tr><td><code>spike-2x</code></td><td>RNF-NFR-029</td><td>Con 2× la carga pico: 5xx &lt; 1 %; rutas críticas dentro de meta</td></tr><tr><td>Carga mixta (exportación de un tenant mientras otro cobra)</td><td>RNF-NFR-020, RNF-NFR-021</td><td>Cola <code>bulk</code> saturada no aumenta más de 10 % el p95 interactivo; cuota de 4 lotes concurrentes por tenant</td></tr><tr><td>Lighthouse CI móvil (landing, login, &quot;Mis servicios&quot;, &quot;Mis facturas&quot;, &quot;Pagar&quot;, &quot;Nuevo reclamo&quot;)</td><td>RNF-NFR-008, RNF-NFR-185</td><td>LCP ≤ 2,5 s; INP ≤ 200 ms; CLS ≤ 0,1; puntaje ≥ 85 en gama baja</td></tr><tr><td>Lighthouse CI escritorio (AdminShell, DataTable, ficha 360)</td><td>RNF-NFR-009</td><td>LCP ≤ 3 s; puntaje ≥ 80</td></tr><tr><td>Autoescalado</td><td>RNF-NFR-023</td><td>Escala de 2 a 6 réplicas en ≤ 5 min</td></tr></tbody></table><h3 id="_6-3-carga-de-facturacion-masiva-y-procesos-batch" tabindex="-1">6.3 Carga de facturación masiva y procesos batch <a class="header-anchor" href="#_6-3-carga-de-facturacion-masiva-y-procesos-batch" aria-label="Permalink to &quot;6.3 Carga de facturación masiva y procesos batch&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Proceso</th><th>Requisito</th><th>Meta</th><th>Estado en la fuente</th></tr></thead><tbody><tr><td><code>fac:emitir-lote</code> (cálculo, comprobantes, asientos y cuenta corriente)</td><td>RNF-NFR-010</td><td>50.000 suministros ≤ 60 min (≥ 14 comprobantes/s) con 4 workers; 150.000 ≤ 3 h; sin duplicados al matar un worker al 50 %</td><td>A validar (PA-NFR-04, asumida por DEC-072)</td></tr><tr><td>Autorización ARCA del lote</td><td>RNF-NFR-011</td><td>≥ 10 comprobantes/s; lote de 50.000 ≤ 2 h con ARCA normal; prueba de caos con timeouts</td><td>A validar (PA-NFR-04)</td></tr><tr><td>PDF y distribución</td><td>RNF-NFR-012</td><td>PDF 50.000 ≤ 60 min; distribución 50.000 ≤ 4 h; PDF individual p95 ≤ 3 s</td><td>Adoptado</td></tr><tr><td>Importaciones</td><td>RNF-NFR-015</td><td>Vista previa de 10.000 filas ≤ 60 s; confirmación de 50.000 registros ≤ 15 min</td><td>Adoptado</td></tr><tr><td>Otros batch (mora, débitos, rendiciones, asientos, sueldos, exportación)</td><td>RNF-NFR-016</td><td>Metas por proceso en O5, O6, O8, O9 y O11</td><td>A validar (PA-NFR-04)</td></tr><tr><td>Capacidad del tenant grande con 5 años de historia</td><td>RNF-NFR-024</td><td>Metas interactivas de T08 §7.2 cumplidas; prueba trimestral y antes de cerrar O4, O5, O6, O7 y O11</td><td>Adoptado</td></tr></tbody></table><p><strong>Cuándo:</strong> obligatorias antes de cerrar O0 (línea base), O4, O5, O6, O7 y O11, y semanalmente en <code>staging</code> desde O4 (RNF-NFR-145).</p><h3 id="_6-4-resistencia-y-caos" tabindex="-1">6.4 Resistencia y caos <a class="header-anchor" href="#_6-4-resistencia-y-caos" aria-label="Permalink to &quot;6.4 Resistencia y caos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prueba</th><th>Requisito</th><th>Meta</th></tr></thead><tbody><tr><td>Resistencia de 8 h al 70 % del pico</td><td>RNF-NFR-146</td><td>Memoria estable (± 10 %); degradación ≤ 10 %</td></tr><tr><td>Caída de worker, de primario de Mongo y de Redis</td><td>RNF-NFR-013, RNF-NFR-041, RNF-NFR-048</td><td>Reanudación sin duplicados; sin pérdida de escrituras confirmadas</td></tr><tr><td>Conector lento o caído</td><td>RNF-NFR-027, RNF-NFR-047</td><td>Ninguna ruta interactiva espera más de 15 s; circuit breaker tras 5 fallas en 60 s; tablero muestra el conector degradado en ≤ 2 min</td></tr><tr><td>Tormenta de reintentos</td><td>RNF-NFR-227</td><td>Picos ≤ 2× el tráfico normal</td></tr></tbody></table><h3 id="_6-5-seguridad-owasp-asvs-5-0-nivel-2" tabindex="-1">6.5 Seguridad (OWASP ASVS 5.0 nivel 2) <a class="header-anchor" href="#_6-5-seguridad-owasp-asvs-5-0-nivel-2" aria-label="Permalink to &quot;6.5 Seguridad (OWASP ASVS 5.0 nivel 2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prueba</th><th>Frecuencia</th><th>Meta</th><th>Requisitos</th></tr></thead><tbody><tr><td>Lista ASVS L2 en el repositorio con estado por requisito</td><td>Revisión en cada ola (gate de cierre)</td><td>100 % con estado; ningún &quot;no cumple&quot; en autenticación, sesión, autorización, validación, criptografía, archivos y API al cerrar O1</td><td>RNF-NFR-050</td></tr><tr><td>Modelado de amenazas por módulo e integración</td><td>Antes de construir cada módulo</td><td>Un modelo por anexo y por ficha de integración</td><td>RNF-NFR-051</td></tr><tr><td>SAST (Semgrep/CodeQL con reglas propias) y escaneo de secretos con historial</td><td>Cada PR</td><td>0 hallazgos altos sin resolver</td><td>RNF-NFR-094, RNF-NFR-147</td></tr><tr><td>SCA de dependencias</td><td>Cada PR</td><td>Bloquea vulnerabilidades altas o críticas con corrección; remediación crítica ≤ 7 días, alta ≤ 30, media ≤ 90</td><td>RNF-NFR-092</td></tr><tr><td>SBOM, escaneo y firma de imágenes</td><td>Cada versión</td><td>100 % de versiones con SBOM y firma</td><td>RNF-NFR-093, RNF-NFR-236</td></tr><tr><td>Suite de inyección NoSQL, SSRF, XSS, cargas de archivos, CORS y encabezados</td><td>Cada PR</td><td>0 hallazgos</td><td>RNF-NFR-147, RNF-NFR-235</td></tr><tr><td>Fuzzing desde OpenAPI</td><td>Nocturno</td><td>0 hallazgos altos abiertos al liberar</td><td>RNF-NFR-147</td></tr><tr><td>DAST (OWASP ZAP)</td><td>Línea base por liberación; completo mensual autenticado con dos tenants</td><td>0 críticos o altos abiertos</td><td>RNF-NFR-095</td></tr><tr><td>Pruebas de penetración externas</td><td>Antes del go-live del piloto, anual y tras cambios mayores de autenticación, pagos o multitenancy</td><td>0 hallazgos críticos o altos abiertos al go-live</td><td>RNF-NFR-095 (A validar, PA-NFR-17 asumida por DEC-072)</td></tr><tr><td>Tokens y sesión: algoritmo o <code>kid</code> inválido, tokens fuera del almacenamiento web, CSRF, revocación ≤ 60 s</td><td>Cada PR (e2e y contrato)</td><td>0 tokens aceptados inválidos; 0 tokens en almacenamiento web</td><td>RNF-NFR-062 a 065</td></tr><tr><td>Credential stuffing simulado (10.000 intentos)</td><td>Por ola de IAM</td><td>0 cuentas comprometidas</td><td>RNF-NFR-066</td></tr><tr><td>Batería adversarial de IA (inyección de instrucciones en fotos, mensajes y PDF)</td><td>Cada función de IA</td><td>0 éxitos</td><td>RNF-NFR-098</td></tr><tr><td>Alertas de seguridad (acceso cruzado entre tenants, picos de login fallido, etc.)</td><td>Simulacro trimestral</td><td>Detección ≤ 5 min</td><td>RNF-NFR-133</td></tr><tr><td>Datos personales en telemetría y logs</td><td>Muestreo semanal y escaneo diario</td><td>0 coincidencias de PII o secretos</td><td>RNF-NFR-121, RNF-NFR-139</td></tr></tbody></table><h3 id="_6-6-accesibilidad" tabindex="-1">6.6 Accesibilidad <a class="header-anchor" href="#_6-6-accesibilidad" aria-label="Permalink to &quot;6.6 Accesibilidad&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prueba</th><th>Meta</th><th>Requisitos</th></tr></thead><tbody><tr><td>axe-core dentro de Playwright en recorridos esenciales</td><td>0 violaciones <code>serious</code> o <code>critical</code> por PR</td><td>RNF-NFR-155</td></tr><tr><td>Auditoría manual por ola con teclado y lectores de pantalla (NVDA, TalkBack, VoiceOver), zoom 200 % y reflujo a 320 px</td><td>Informe por ola sin bloqueantes</td><td>RNF-NFR-181</td></tr><tr><td>Contraste del branding del tenant</td><td>0 combinaciones publicadas bajo 4,5:1 (texto) o 3:1 (componentes)</td><td>RNF-NFR-182</td></tr><tr><td>Objetivo general</td><td>WCAG 2.2 AA; 100 % de recorridos esenciales operables solo con teclado; no se declara conformidad sin verificación</td><td>RNF-NFR-180 (AGR-032)</td></tr></tbody></table><h3 id="_6-7-respaldo-y-restauracion" tabindex="-1">6.7 Respaldo y restauración <a class="header-anchor" href="#_6-7-respaldo-y-restauracion" aria-label="Permalink to &quot;6.7 Respaldo y restauración&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prueba</th><th>Frecuencia</th><th>Meta</th><th>Requisitos</th></tr></thead><tbody><tr><td>Restauración de plataforma a T−5 min en ambiente aislado con comparación de conteos y hashes</td><td>Mensual automática</td><td>RPO comprometido ≤ 15 min (DEC-063); objetivo interno ≤ 5 min</td><td>RNF-NFR-035, RNF-NFR-043, RNF-NFR-157</td></tr><tr><td>Restauración selectiva de un tenant</td><td>Trimestral con tenant piloto y TEN-001/TEN-002</td><td>RTO por tenant ≤ 4 h (DEC-063); los demás tenants no se afectan</td><td>RNF-NFR-037; escenario 15 de BASE §34</td></tr><tr><td>Restauración con operaciones externas posteriores a la copia</td><td>Simulacro con emisión y pago confirmados después del punto de restauración</td><td>0 emisiones o cobros duplicados</td><td>RNF-NFR-044; ESC-04</td></tr><tr><td>Reaplicación de supresiones posteriores</td><td>En cada simulacro</td><td>100 % reaplicadas antes de habilitar el acceso</td><td>RNF-NFR-045</td></tr><tr><td>Restauración completa de plataforma con cronómetro</td><td>Anual</td><td>RTO comprometido ≤ 8 h; objetivo interno ≤ 4 h</td><td>RNF-NFR-036</td></tr><tr><td>Caída de zona</td><td>Semestral</td><td>≤ 15 min</td><td>RNF-NFR-036</td></tr><tr><td>Backup de 12 meses restaurable con sus claves</td><td>Anual</td><td>100 % restaurable</td><td>RNF-NFR-042</td></tr><tr><td>Recuperación de objetos (100 al azar)</td><td>Trimestral</td><td>Recuperación ≤ 1 h</td><td>RNF-NFR-039</td></tr><tr><td>Recuperación ante desastre regional</td><td>Anual (desde O11)</td><td>RPO ≤ 1 h; RTO ≤ 24 h</td><td>RNF-NFR-046</td></tr><tr><td>Runbooks de restauración, DR, rotación de claves, caída de conector y fuga de credenciales</td><td>Al menos una prueba anual por runbook</td><td>100 % con última prueba ≤ 12 meses</td><td>RNF-NFR-049</td></tr></tbody></table><p>Los resultados se registran en <code>restoreTests</code> con RPO y RTO medidos y acta (RF-NFR-015).</p><hr><h2 id="_7-pruebas-de-migracion-desde-procoop" tabindex="-1">7. Pruebas de migración desde ProCoop <a class="header-anchor" href="#_7-pruebas-de-migracion-desde-procoop" aria-label="Permalink to &quot;7. Pruebas de migración desde ProCoop&quot;">​</a></h2><h3 id="_7-1-criterios-transversales-t07-§17-1" tabindex="-1">7.1 Criterios transversales (T07 §17.1) <a class="header-anchor" href="#_7-1-criterios-transversales-t07-§17-1" aria-label="Permalink to &quot;7.1 Criterios transversales (T07 §17.1)&quot;">​</a></h3><ul><li>Conteo de filas extraídas igual al conteo de origen por tabla, según el manifiesto del snapshot.</li><li>0 rechazos bloqueantes no excluidos; exclusiones aprobadas y listadas (RN-MIG-039).</li><li>100 % de los documentos migrados con <code>legacy</code> y entrada en <code>legacyIdMap</code>.</li><li>Reproceso del mismo snapshot y conjunto de mapeo: 0 cambios (RF-MIG-043; ESC-MIG-01).</li><li>Una corrida del tenant A no lee ni escribe documentos del tenant B.</li><li>Quien ejecuta una corrida no aprueba su conciliación (RN-MIG-041).</li><li>Ninguna credencial de ProCoop aparece en snapshots, staging, logs ni informes (RN-MIG-013).</li><li>Corrida reanudada tras corte forzado del worker sin duplicados (RF-MIG-044).</li></ul><h3 id="_7-2-conciliacion-de-saldos-y-conteos" tabindex="-1">7.2 Conciliación de saldos y conteos <a class="header-anchor" href="#_7-2-conciliacion-de-saldos-y-conteos" aria-label="Permalink to &quot;7.2 Conciliación de saldos y conteos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Regla</th><th>Requisitos</th></tr></thead><tbody><tr><td>Deuda por titular y servicio</td><td>Σ saldos de documentos abiertos migrados = Σ saldos ProCoop; total = cuenta contable de deudores por servicios a la fecha de corte</td><td>RF-MIG-054; T07 §9.8</td></tr><tr><td>Fondos</td><td>Suma de cajas, valores, cupones y bancos = saldo contable de disponibilidades</td><td>RF-MIG-055</td></tr><tr><td>Stock y comodatos</td><td>Cada equipo serializado en un depósito o en una cuenta, nunca en ambos</td><td>RF-MIG-056</td></tr><tr><td>Contabilidad</td><td>Balance de sumas y saldos a la fecha de corte con diferencia 0 por cuenta</td><td>RF-MIG-057</td></tr><tr><td>Tolerancias</td><td>Cantidades 0; importes 0,00 por documento salvo redondeo explicado ≤ 0,01 (PRM-MIG-040); totales por dominio 0,00 explicados</td><td>RN-MIG-040</td></tr><tr><td>Importes</td><td>Conversión a <code>Decimal128</code> sin redondeo: la suma por tabla coincide al centavo con el origen</td><td>RF-MIG-036</td></tr></tbody></table><h3 id="_7-3-muestreo-por-dominio" tabindex="-1">7.3 Muestreo por dominio <a class="header-anchor" href="#_7-3-muestreo-por-dominio" aria-label="Permalink to &quot;7.3 Muestreo por dominio&quot;">​</a></h3><p>T07 §17.2 fija el muestreo mínimo; se ejecuta en cada ensayo integral:</p><table tabindex="0"><thead><tr><th>Dominio</th><th>Muestreo</th><th>Aprueba</th></tr></thead><tbody><tr><td>Personas y cuentas (M01)</td><td>50 fichas al azar comparadas campo por campo</td><td>Responsable de atención o titulares</td></tr><tr><td>Cuadros tarifarios (M04)</td><td>Recalcular 100 facturas del último período cerrado con la versión migrada: mismo resultado</td><td>Responsable de tarifas</td></tr><tr><td>Deuda y cuenta corriente (M07)</td><td>100 cuentas al azar con estado de cuenta idéntico</td><td>Contador y cobranzas</td></tr><tr><td>Cobranzas (M07)</td><td>Imputación idéntica en 100 recibos</td><td>Cobranzas</td></tr><tr><td>Financiaciones (M08)</td><td>Próximo vencimiento y cuota de 30 convenios</td><td>Cobranzas y contador</td></tr><tr><td>Stock (M13)</td><td>30 equipos en comodato verificados en campo o por llamada</td><td>Depósito y contador</td></tr><tr><td>Proveedores (M12)</td><td>30 proveedores (CUIT, condición IVA, CBU enmascarado)</td><td>Compras y contador</td></tr><tr><td>Sueldos (M16)</td><td>Reliquidar un período cerrado: mismo neto en el 100 % de los legajos o diferencia explicada</td><td>RRHH y contador</td></tr><tr><td>Técnica y CRM (M10/M09)</td><td>Estado y responsable de 30 abiertos</td><td>Responsable técnico o de atención</td></tr><tr><td>Portal y usuarios (M19/T02)</td><td>Un socio de prueba activa su cuenta y ve sus cuentas</td><td>Atención</td></tr></tbody></table><h3 id="_7-4-corrida-paralela-con-procoop" tabindex="-1">7.4 Corrida paralela con ProCoop <a class="header-anchor" href="#_7-4-corrida-paralela-con-procoop" aria-label="Permalink to &quot;7.4 Corrida paralela con ProCoop&quot;">​</a></h3><ul><li>GoodApps simula el ciclo sin CAE, sin numeración fiscal, sin publicar deuda y sin notificar (RF-MIG-070, RN-MIG-030).</li><li>Se comparan factura por factura cantidades, importes por concepto, impuestos, totales, vencimientos y apertura por servicio (RF-MIG-072), y en forma complementaria mora, cobranzas imputadas y asientos simulados (RF-MIG-074).</li><li>Cada diferencia se clasifica (<code>equal</code>, <code>rounding</code>, <code>configuration</code>, <code>migratedData</code>, <code>intendedFix</code>, <code>goodappsDefect</code>, <code>procoopKnownDefect</code>); <code>goodappsDefect</code> obliga a ticket y nueva simulación (T07 §8.6).</li><li><strong>Criterio de aprobación</strong> (T07 §17.4): coincidencia o diferencia explicada en el 100 % de las facturas; 2 ciclos consecutivos aprobados por servicio (PRM-MIG-041; PA-MIG-02 asumida por DEC-072); 0 diferencias sin explicar (PRM-MIG-042); emparejamiento ≥ 99,9 % con los no emparejados justificados.</li></ul><h3 id="_7-5-escenarios-de-migracion" tabindex="-1">7.5 Escenarios de migración <a class="header-anchor" href="#_7-5-escenarios-de-migracion" aria-label="Permalink to &quot;7.5 Escenarios de migración&quot;">​</a></h3><p>ESC-MIG-01 a ESC-MIG-10 de T07 §17.3 (repetición de lote, factura agrupada que mezcla titulares, pago parcial histórico, identificadores de 10 dígitos, códigos SIRO extendidos, comprobantes ambiguos en rendición, reproceso con conflicto, snapshot real en <code>test</code>, rollback posterior a la primera emisión fiscal y usuario del portal con correo duplicado). El criterio de salida de O11 exige además repetir la migración completa dos veces con el mismo resultado y probar el rollback (<code>03</code> §15.2).</p><h3 id="_7-6-anonimizacion-de-copias-para-ensayo" tabindex="-1">7.6 Anonimización de copias para ensayo <a class="header-anchor" href="#_7-6-anonimizacion-de-copias-para-ensayo" aria-label="Permalink to &quot;7.6 Anonimización de copias para ensayo&quot;">​</a></h3><ul><li>Los ensayos con copia de ProCoop se ejecutan solo en un ambiente aislado de migración autorizado por la cooperativa, nunca en <code>local</code>, <code>ci</code>, <code>staging</code> ni <code>demo</code>, con constancia de eliminación al terminar (RNF-NFR-154; T08 §19; PA-NFR-19 asumida por DEC-072).</li><li>Verificación posterior a la anonimización: búsqueda de patrones de DNI, CUIT, correo y teléfono del origen en el destino con 0 coincidencias (T07 §9.10).</li><li>Un snapshot no anonimizado se rechaza en ambientes de prueba (RF-MIG-096; ESC-MIG-08).</li></ul><hr><h2 id="_8-datos-de-prueba" tabindex="-1">8. Datos de prueba <a class="header-anchor" href="#_8-datos-de-prueba" aria-label="Permalink to &quot;8. Datos de prueba&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Regla</th><th>Contenido</th><th>Requisitos</th></tr></thead><tbody><tr><td>Origen</td><td>Datos 100 % ficticios y generados; prohibido usar datos reales o de la DEMO de ProCoop</td><td>RN-NFR-014, RNF-NFR-160, RN-PLA-050</td></tr><tr><td>Generación</td><td>Fábricas en <code>packages/shared/testing</code> con generador determinista por semilla: personas, domicilios, DNI y CUIT con dígito verificador válido en rangos ficticios, CBU de prueba, teléfonos de rango reservado, correos en dominio de prueba</td><td>RNF-NFR-160</td></tr><tr><td>Marcado</td><td>Tenants y personas de prueba marcados como ficticios (ver observación OBS-03)</td><td>RNF-NFR-160; <code>03</code> R13</td></tr><tr><td>Juego canónico</td><td>TEN-001 &quot;Cooperativa Ejemplo A&quot; y TEN-002 &quot;Cooperativa Ejemplo B&quot; con códigos internos iguales, titulares hermanos con domicilio compartido, socio con dos servicios, agrupación y separación, casos ESC-01 a ESC-05 y terminologías Socio/Asociado; script idempotente bloqueado en producción</td><td>RNF-NFR-161, RF-PLA-113</td></tr><tr><td>Volumen</td><td>Dataset sintético de tenant grande solo en <code>staging</code></td><td>T08 §18</td></tr><tr><td>Datos demo por anexo</td><td>Sección 18 de cada anexo; para el piloto, los datos de T12 parte 1 (Ana Demo, INT-100, ONT-DEMO-0001)</td><td><code>03</code> R14</td></tr><tr><td>Control</td><td>Escaneo en CI de patrones de DNI/CUIT reales conocidos y de dominios reales en fixtures</td><td>RNF-NFR-160</td></tr><tr><td>Integraciones</td><td>Conectores en modo prueba con simulador; ARCA solo en homologación con certificado generado para pruebas; sin envíos a destinatarios reales</td><td><code>03</code> R13; RN-NFR-015; DEC-053</td></tr></tbody></table><hr><h2 id="_9-ambientes-de-prueba" tabindex="-1">9. Ambientes de prueba <a class="header-anchor" href="#_9-ambientes-de-prueba" aria-label="Permalink to &quot;9. Ambientes de prueba&quot;">​</a></h2><p>El detalle de ambientes es de T01 §7.10 (RNF-NFR-170 remite a T01; ver observación OBS-02).</p><table tabindex="0"><thead><tr><th>Ambiente</th><th>Uso en la estrategia</th><th>Datos</th><th>Integraciones</th></tr></thead><tbody><tr><td><code>local</code></td><td>Pruebas del desarrollador</td><td>Juego canónico ficticio</td><td>Simuladas</td></tr><tr><td><code>ci</code></td><td>Pruebas automáticas efímeras por PR</td><td>Juego canónico</td><td>Simuladas</td></tr><tr><td><code>dev</code></td><td>Integración continua del equipo</td><td>Canónico y datos de desarrollo</td><td>Simuladas u homologación</td></tr><tr><td><code>staging</code></td><td>Preproducción: e2e completo, aceptación, carga, DAST, simulacros</td><td>Canónico más volumen sintético</td><td>Homologación</td></tr><tr><td><code>sandbox</code></td><td>Pruebas de configuración de cada cooperativa (tenant gemelo) y aceptación de usuario</td><td>Ficticios o copia anonimizada aprobada (PA-PLA-07)</td><td>Solo homologación</td></tr><tr><td><code>demo</code></td><td>Demostraciones</td><td>Precarga de demostración</td><td>Simuladas</td></tr><tr><td><code>prod</code></td><td>Monitoreo sintético con tenant de prueba aislado, no facturable y sin emisión real</td><td>—</td><td>Producción, sin efectos reales para el tenant de prueba</td></tr><tr><td>Ambiente aislado de migración</td><td>Ensayos con copia de ProCoop autorizada</td><td>Copia tratada, eliminada al terminar</td><td>—</td></tr></tbody></table><p>Notas: los ambientes no productivos muestran una banda visible (&quot;PRUEBA&quot;, &quot;DEMO&quot;) y no tienen credenciales productivas (RN-PLA-034, RNF-NFR-099); el monitoreo sintético en producción está definido en RNF-NFR-137.</p><hr><h2 id="_10-automatizacion-en-integracion-continua" tabindex="-1">10. Automatización en integración continua <a class="header-anchor" href="#_10-automatizacion-en-integracion-continua" aria-label="Permalink to &quot;10. Automatización en integración continua&quot;">​</a></h2><h3 id="_10-1-pipeline-por-pr" tabindex="-1">10.1 Pipeline por PR <a class="header-anchor" href="#_10-1-pipeline-por-pr" aria-label="Permalink to &quot;10.1 Pipeline por PR&quot;">​</a></h3><p>Secuencia de RNF-NFR-164 (duración p50 ≤ 15 min, p95 ≤ 25 min), alineada con el pipeline de T01 §7.10:</p>',93)),(a(),i(s,null,{default:t(()=>[n(o,{id:"mermaid-2808",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22Instalaci%C3%B3n%20reproducible%20(npm%20ci)%22%5D%20--%3E%20B%5B%22Lint%20y%20formato%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Chequeos%20est%C3%A1ticos%3A%20SAST%2C%20secretos%2C%20SCA%2C%20licencias%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Unitarias%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Integraci%C3%B3n%20con%20Mongo%20y%20Redis%20reales%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22Aislamiento%20y%20permisos%20negativos%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22Contrato%3A%20OpenAPI%20y%20eventos%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22Build%20de%20im%C3%A1genes%22%5D%0A%20%20%20%20H%20--%3E%20I%5B%22Escaneo%20de%20im%C3%A1genes%20y%20SBOM%22%5D%0A%20%20%20%20I%20--%3E%20J%5B%22E2E%20de%20humo%22%5D%0A%20%20%20%20J%20--%3E%20K%5B%22Informe%20y%20trazabilidad%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<h3 id="_10-2-scripts-estandar" tabindex="-1">10.2 Scripts estándar <a class="header-anchor" href="#_10-2-scripts-estandar" aria-label="Permalink to &quot;10.2 Scripts estándar&quot;">​</a></h3><p>Definidos en <code>03</code> §2.5: <code>npm run lint</code>, <code>npm run check:structure</code>, <code>npm test</code>, <code>npm run test:isolation</code>, <code>npm run test:e2e -- --grep @Ox</code>, <code>npm run seed:demo</code> (se niega a correr en producción) y <code>npm run trace:check</code> (falla si un RF del prompt no tiene prueba que lo cite o si una prueba cita un ID inexistente).</p><h3 id="_10-3-gates-de-promocion" tabindex="-1">10.3 Gates de promoción <a class="header-anchor" href="#_10-3-gates-de-promocion" aria-label="Permalink to &quot;10.3 Gates de promoción&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Transición</th><th>Condición</th><th>Requisitos</th></tr></thead><tbody><tr><td><code>main</code> → <code>staging</code></td><td>Automática con CI verde</td><td>RNF-NFR-165</td></tr><tr><td><code>staging</code> → producción</td><td>Evidencia completa (pruebas, cobertura, SCA, SAST, DAST, imágenes escaneadas, SBOM, carga cuando corresponde, aprobaciones); DAST de línea base sin altos; e2e completo verde; aprobación del responsable de la liberación</td><td>RF-NFR-022, RNF-NFR-165, RF-PLA-114</td></tr><tr><td>Producción por anillos</td><td>Interno, piloto y general, con feature flags por tenant</td><td>RF-PLA-149 (PA-PLA-13 asumida), RNF-NFR-169</td></tr><tr><td>Rollback de despliegue</td><td>≤ 15 min, probado en cada ola</td><td>RNF-NFR-167</td></tr><tr><td>Migraciones de esquema</td><td>Expandir/contraer, idempotentes, como paso del despliegue; prueba N−1 → N con tráfico</td><td>RNF-NFR-168, RN-NFR-022</td></tr></tbody></table><h3 id="_10-4-proteccion-de-ramas-y-pruebas-inestables" tabindex="-1">10.4 Protección de ramas y pruebas inestables <a class="header-anchor" href="#_10-4-proteccion-de-ramas-y-pruebas-inestables" aria-label="Permalink to &quot;10.4 Protección de ramas y pruebas inestables&quot;">​</a></h3><ul><li><code>main</code> protegida, PR obligatorio, ≥ 1 revisión (≥ 2 y del dueño de código para paquetes compartidos, tenancy, autorización, bóveda, pagos, fiscal e IaC) (RNF-NFR-166).</li><li>Una prueba inestable va a cuarentena con ticket y responsable en ≤ 24 h y se corrige o elimina en ≤ 7 días; ≤ 1 % de ejecuciones con reintentos (RNF-NFR-162).</li></ul><hr><h2 id="_11-criterios-de-entrada-y-salida-por-ola-y-definicion-de-terminado" tabindex="-1">11. Criterios de entrada y salida por ola y definición de terminado <a class="header-anchor" href="#_11-criterios-de-entrada-y-salida-por-ola-y-definicion-de-terminado" aria-label="Permalink to &quot;11. Criterios de entrada y salida por ola y definición de terminado&quot;">​</a></h2><h3 id="_11-1-criterios-de-entrada-de-una-ola" tabindex="-1">11.1 Criterios de entrada de una ola <a class="header-anchor" href="#_11-1-criterios-de-entrada-de-una-ola" aria-label="Permalink to &quot;11.1 Criterios de entrada de una ola&quot;">​</a></h3><ol><li>La ola anterior cumple su criterio de salida y su prompt de integración está verde (<code>03</code> R1).</li><li>Arranque de sesión con PRO-GEN-01 y lectura de las secciones indicadas (<code>03</code> §3, R3).</li><li>Modelo de amenazas del módulo o integración disponible antes de construirlo (RNF-NFR-051).</li><li>Huecos de <code>05-registro-huecos.md</code> y PA asumidas de la ola identificados (<code>03</code> R8, R9).</li><li>Juego canónico de datos ampliado con la precarga de la sección 18 de los anexos de la ola (<code>03</code> R14).</li></ol><h3 id="_11-2-criterios-de-salida-comunes-t08-§17-3" tabindex="-1">11.2 Criterios de salida comunes (T08 §17.3) <a class="header-anchor" href="#_11-2-criterios-de-salida-comunes-t08-§17-3" aria-label="Permalink to &quot;11.2 Criterios de salida comunes (T08 §17.3)&quot;">​</a></h3><ol><li>Aislamiento: la suite cubre el 100 % de rutas y jobs nuevos, sin fallas (RNF-NFR-148).</li><li>Permisos negativos: cada capability nueva tiene su caso (RNF-NFR-150).</li><li>Reintentos e interrupción: cada job y operación económica nueva tiene prueba de falla a mitad y doble envío (RNF-NFR-151).</li><li>Conciliación: desde O5, JOB-NFR-06 sin diferencias en el dataset canónico tras el recorrido de la ola.</li><li>Rendimiento: metas de T08 §7 aplicables a la ola cumplidas en <code>staging</code> (RNF-NFR-145).</li><li>Seguridad: matriz ASVS actualizada y 0 hallazgos altos abiertos (RNF-NFR-050, RNF-NFR-092, RNF-NFR-095).</li><li>Privacidad: campos nuevos con <code>x-pii</code>; inventario y registro de tratamientos actualizados (RF-NFR-001, RF-NFR-002).</li><li>Accesibilidad: 0 violaciones <code>serious</code> o <code>critical</code> (RNF-NFR-155).</li><li>Observabilidad: métricas, logs y trazas de los procesos nuevos visibles; alertas con runbook (RNF-NFR-125, RNF-NFR-132).</li><li>Evidencia: liberación de cierre de ola con <code>qualityEvidence</code> completa y aprobada (RF-NFR-022).</li><li>Cierre formal con PRO-GEN-02: todos los RF de la ola <code>Implementado</code> o <code>Parcial</code> con la parte de la ola cumplida, y evidencia en <code>docs/evidencias/Ox/</code> (<code>03</code> §3, R20).</li></ol><h3 id="_11-3-criterio-de-salida-especifico-por-ola" tabindex="-1">11.3 Criterio de salida específico por ola <a class="header-anchor" href="#_11-3-criterio-de-salida-especifico-por-ola" aria-label="Permalink to &quot;11.3 Criterio de salida específico por ola&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ola</th><th>Hito demostrable (resumen de <code>03</code>)</th><th>Pruebas extremo a extremo de referencia</th><th>Carga obligatoria</th></tr></thead><tbody><tr><td>O0</td><td>Tenant demo con login, menú vacío filtrado por capability y suite de aislamiento verde</td><td>ESC-01..05 de T01 y T08 en lo aplicable; ESC-UXD-01..25; TST-IAM; CA-WFL; CA-INT</td><td>Sí (línea base)</td></tr><tr><td>O1</td><td>Alta asistida de una cooperativa con usuarios, roles, 2FA y configuración publicada</td><td>CU-MT-01; TST-IAM; ESC-CFG-01..30; CA-INT-01..15; ESC-MIG de proyecto y corrida; ESC-04</td><td>—</td></tr><tr><td>O2</td><td>Un socio se registra y solicita Internet; el contrato queda <code>requested</code></td><td>ESC-SRV-INT-01 hasta la creación del contrato; CU de M01, M02, M09, T09, M19</td><td>—</td></tr><tr><td>O3</td><td>Servicio instalado con ONT en comodato, sincronización offline sin duplicar y aprovisionamiento confirmado</td><td>ESC-SRV-INT-01 hasta la activación; CU de M10, M13, M09</td><td>—</td></tr><tr><td>O4</td><td>Primera factura electrónica con CAE</td><td>ESC-SRV-INT-01; CU de M04, M05, M06</td><td>Sí</td></tr><tr><td>O5</td><td>Pago online imputado, rendido y asentado</td><td>ESC-COB-R01 y ESC-01 (M07 §17; ver OBS-05); CU de M07, M14, M15, M17</td><td>Sí</td></tr><tr><td>O6</td><td>Piloto Internet completo de punta a punta (DEC-005)</td><td>ESC-SRV-INT-01..07 en un solo recorrido</td><td>Sí</td></tr><tr><td>O7</td><td>Facturación de energía con lecturas</td><td>ESC de energía y agua de T12 parte 1 §4.7 y §5.7 (antes citaba parte 2); CU de M03, M04, M06, M10; para habilitar la migración de LAG, AC-16 a AC-19 (sección 15.2)</td><td>Sí</td></tr><tr><td>O8</td><td>Cierre contable mensual</td><td>CU de M12, M14, M15, M06, M16 (CU-28)</td><td>—</td></tr><tr><td>O9</td><td>Liquidación mensual con F.931 y LSD, dos períodos en paralelo</td><td>CU de M16</td><td>—</td></tr><tr><td>O10</td><td>Asamblea y servicios sociales operativos</td><td>CU de M17, M18, M09; ESC de telefonía y TV de T12 parte 1 §2.7 y §3.7 (antes citaba parte 2)</td><td>—</td></tr><tr><td>O11</td><td>Migración repetida dos veces con el mismo resultado; paralelo con diferencias explicadas; ensayos de corte comercial y administrativo con rollback probado</td><td>ESC de T07 §17 y de T10 §17; AC-20 para el paralelo de LAG</td><td>Sí</td></tr></tbody></table><p>La columna &quot;Carga obligatoria&quot; refleja RNF-NFR-145; RNF-NFR-024 exige además la prueba de capacidad del tenant grande antes de cerrar O4, O5, O6, O7 y O11.</p><h3 id="_11-4-definicion-de-terminado" tabindex="-1">11.4 Definición de terminado <a class="header-anchor" href="#_11-4-definicion-de-terminado" aria-label="Permalink to &quot;11.4 Definición de terminado&quot;">​</a></h3><p>Se aplica la definición común de <code>03</code> R16, coherente con la maestra §16:</p><ol><li>Todos los RF del prompt cumplen su criterio de aceptación con prueba automatizada que cita el ID.</li><li>Pruebas de permisos negativos y aislamiento verdes.</li><li>Sin textos fijos en la interfaz (todo por diccionario).</li><li>Auditoría y eventos emitidos en cada cambio persistente.</li><li>Esquemas Zod y OpenAPI actualizados.</li><li>Seeds idempotentes y seeds de demostración bloqueados en producción.</li><li><code>lint</code>, <code>check:structure</code>, <code>test</code>, <code>test:isolation</code> y el e2e del prompt en verde.</li><li>Matriz de trazabilidad actualizada (<code>03</code> R19).</li><li>PR con la plantilla de <code>03</code> R18.</li></ol><hr><h2 id="_12-gestion-de-defectos" tabindex="-1">12. Gestión de defectos <a class="header-anchor" href="#_12-gestion-de-defectos" aria-label="Permalink to &quot;12. Gestión de defectos&quot;">​</a></h2><h3 id="_12-1-severidades" tabindex="-1">12.1 Severidades <a class="header-anchor" href="#_12-1-severidades" aria-label="Permalink to &quot;12.1 Severidades&quot;">​</a></h3><p>La especificación define severidades para incidentes de operación (SEV1 a SEV4, RNF-NFR-134) y para tickets de soporte (Crítica, Alta, Media, Baja, RNF-NFR-252), pero no una escala específica para defectos detectados en pruebas. Este documento propone aplicar a los defectos la misma escala de cuatro niveles, para que un defecto y el incidente que causaría en producción se clasifiquen igual:</p><table tabindex="0"><thead><tr><th>Severidad</th><th>Criterio para un defecto</th><th>Efecto sobre la ola o la liberación</th></tr></thead><tbody><tr><td>S1 — Crítica</td><td>Fuga entre tenants; diferencia monetaria no explicada; duplicado de cobro, comprobante o numeración fiscal; pérdida de datos; vulnerabilidad crítica; operación de facturación, cobranza o emisión imposible</td><td>Bloquea el cierre de la ola y la promoción a producción</td></tr><tr><td>S2 — Alta</td><td>Función principal degradada sin alternativa; falla de una suite obligatoria (aislamiento, permisos, idempotencia); vulnerabilidad alta; violación <code>serious</code> o <code>critical</code> de accesibilidad; meta de rendimiento incumplida en una ruta crítica</td><td>Bloquea el cierre de la ola (T08 §17.3)</td></tr><tr><td>S3 — Media</td><td>Función secundaria con alternativa; desvío de una meta no crítica; texto o etiqueta incorrecta</td><td>No bloquea si tiene ticket, responsable y ola de corrección</td></tr><tr><td>S4 — Baja</td><td>Cosmético o de mejora</td><td>No bloquea</td></tr></tbody></table><p>Plazos de corrección por severidad: <strong>a definir</strong>, salvo los que fija la especificación para vulnerabilidades (crítica ≤ 7 días, alta ≤ 30 días, media ≤ 90 días; RNF-NFR-092) y para pruebas inestables (RNF-NFR-162).</p><h3 id="_12-2-flujo" tabindex="-1">12.2 Flujo <a class="header-anchor" href="#_12-2-flujo" aria-label="Permalink to &quot;12.2 Flujo&quot;">​</a></h3><ol><li>Registro del defecto con los IDs afectados (RF, RN, RNF, ESC) y la evidencia (salida de la prueba, capturas con datos ficticios). La herramienta de registro de defectos es <strong>a definir</strong>.</li><li>Corrección con el prompt PRO-GEN-03: primero se escribe la prueba que reproduce la falla, con el ID en el nombre; luego se corrige; no se amplía el alcance (<code>03</code> §3).</li><li>Si la corrección exige cambiar la especificación, se registra una PA nueva en <code>02-preguntas-abiertas.md</code> y se detiene (<code>03</code> R6).</li><li>Cierre con la matriz actualizada y PR <code>fix(&amp;lt;mod&gt;): ...</code> con los IDs.</li><li>En producción, los incidentes siguen el circuito de RNF-NFR-134 (post-mortem obligatorio para SEV1 y SEV2).</li></ol><hr><h2 id="_13-trazabilidad-requisito-→-caso-de-prueba" tabindex="-1">13. Trazabilidad requisito → caso de prueba <a class="header-anchor" href="#_13-trazabilidad-requisito-→-caso-de-prueba" aria-label="Permalink to &quot;13. Trazabilidad requisito → caso de prueba&quot;">​</a></h2><h3 id="_13-1-cadena-de-trazabilidad" tabindex="-1">13.1 Cadena de trazabilidad <a class="header-anchor" href="#_13-1-cadena-de-trazabilidad" aria-label="Permalink to &quot;13.1 Cadena de trazabilidad&quot;">​</a></h3>',29)),(a(),i(s,null,{default:t(()=>[n(o,{id:"mermaid-3357",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20R%5B%22Requisito%3A%20RF%2C%20RN%2C%20RNF%20del%20anexo%22%5D%20--%3E%20C%5B%22Criterio%20de%20aceptaci%C3%B3n%3A%20columna%20de%20la%20tabla%20de%20RF%22%5D%0A%20%20%20%20C%20--%3E%20E%5B%22Escenario%3A%20ESC%20o%20CU%20de%20la%20secci%C3%B3n%2017%20del%20anexo%22%5D%0A%20%20%20%20E%20--%3E%20T%5B%22Caso%20automatizado%20que%20cita%20el%20ID%20en%20su%20nombre%22%5D%0A%20%20%20%20T%20--%3E%20P%5B%22Prompt%20PRO-Ox-NN%20y%20PR%22%5D%0A%20%20%20%20P%20--%3E%20M%5B%22Matriz%2004%3A%20Estado%20de%20implementaci%C3%B3n%22%5D%0A%20%20%20%20M%20--%3E%20I%5B%22Informe%20de%20liberaci%C3%B3n%20con%20cobertura%20por%20requisito%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<h3 id="_13-2-como-se-usan-las-fuentes" tabindex="-1">13.2 Cómo se usan las fuentes <a class="header-anchor" href="#_13-2-como-se-usan-las-fuentes" aria-label="Permalink to &quot;13.2 Cómo se usan las fuentes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fuente</th><th>Uso en la trazabilidad</th></tr></thead><tbody><tr><td>Columna &quot;Criterio de aceptación&quot; de la tabla de RF (sección 5 de cada anexo)</td><td>Cada RF tiene al menos un caso automatizado que verifica ese criterio</td></tr><tr><td>Sección 17 de cada anexo (ESC-<code>&amp;lt;COD&gt;</code>-NN, CU, CA, TST, criterios por dominio)</td><td>Casos de integración y extremo a extremo; se nombran con el ID del escenario</td></tr><tr><td>ESC-01 a ESC-05 (AGR) y escenarios numerados de BASE §34</td><td>Casos transversales; T08 §17.1 y §17.2 indican qué RNF los verifican</td></tr><tr><td>RNF de T08 (columna &quot;Criterio verificable&quot;)</td><td>Casos de CI, carga, seguridad y simulacros</td></tr><tr><td>Fichas de T12 (ESC-SRV-INT y equivalentes por servicio)</td><td>Recorridos extremo a extremo de cada vertical</td></tr><tr><td><code>04-matriz-trazabilidad.md</code> §15 (RF y RNF → prompt)</td><td>Indica qué prompt construye y prueba cada requisito</td></tr><tr><td>Sección &quot;Estado de implementación&quot; de la matriz 04 (creada por R19)</td><td>Fila por RF con prompt, estado, PR, archivos de prueba y fecha</td></tr></tbody></table><h3 id="_13-3-reglas" tabindex="-1">13.3 Reglas <a class="header-anchor" href="#_13-3-reglas" aria-label="Permalink to &quot;13.3 Reglas&quot;">​</a></h3><ul><li>Cada caso declara en su nombre los IDs que verifica (por ejemplo <code>RF-PER-001 crea persona física...</code> o <code>ESC-SRV-INT-01 ...</code>) (<code>03</code> R15; RNF-NFR-163).</li><li>El 100 % de los requisitos <code>Núcleo</code> de la ola tiene al menos una prueba; el informe de liberación lista la cobertura por requisito (RNF-NFR-163; IND-NFR-09).</li><li><code>npm run trace:check</code> falla si un RF no tiene prueba o si una prueba cita un ID inexistente (<code>03</code> R19).</li></ul><hr><h2 id="_14-roles-y-responsabilidades" tabindex="-1">14. Roles y responsabilidades <a class="header-anchor" href="#_14-roles-y-responsabilidades" aria-label="Permalink to &quot;14. Roles y responsabilidades&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rol</th><th>Responsabilidad en las pruebas</th><th>Fuente</th></tr></thead><tbody><tr><td>Equipo de desarrollo (con Cursor IA por prompts)</td><td>Escribe las pruebas de cada prompt (unitarias, integración, permisos, aislamiento, idempotencia, e2e) y mantiene la trazabilidad</td><td>Maestra §16; <code>03</code> R15, R19</td></tr><tr><td>Dueño de código</td><td>Revisión obligatoria de cambios en paquetes compartidos, tenancy, autorización, bóveda, pagos, fiscal e IaC</td><td>RNF-NFR-166</td></tr><tr><td>Responsable de la liberación</td><td>Aprueba la promoción a producción con evidencia completa</td><td>RNF-NFR-165</td></tr><tr><td>Oficial de seguridad / Seguridad de plataforma (P-SEC)</td><td>Revisa la matriz ASVS como gate de cierre de ola; gestiona DAST, pentest y simulacros de alertas</td><td>RNF-NFR-050, RNF-NFR-095, RNF-NFR-133</td></tr><tr><td>Operaciones técnicas (P-OPS)</td><td>Ejecuta pruebas de carga, caos, restauración y DR; mantiene <code>restoreTests</code></td><td>T08 §8; RNF-NFR-043</td></tr><tr><td>Líder e implementador de migración (plataforma)</td><td>Ejecuta ensayos, paralelo y corte; no aprueba sus propias conciliaciones</td><td>T07 §4; RN-MIG-041</td></tr><tr><td>Responsables funcionales de dominio y contador de la cooperativa</td><td>Aprueban conciliaciones y diferencias del paralelo; ejecutan la aceptación de usuario de su dominio</td><td>T07 §4, §17.2</td></tr><tr><td>Responsable de la cooperativa (gerencia o consejo)</td><td>Aprueba paralelo, by-pass, corte y firma el acta de aceptación</td><td>T07 §4</td></tr><tr><td>Usuarios clave de la cooperativa piloto (personal de LAG)</td><td>Ejecutan los casos de aceptación de usuario en <code>sandbox</code> o <code>staging</code> y los de su migración (AC-16 a AC-20)</td><td>AGR §7 etapa F; DEC-088</td></tr></tbody></table><p>La asignación nominal de personas a estos roles es <strong>a definir</strong>.</p><hr><h2 id="_15-casos-de-aceptacion-del-piloto-internet-con-datos-sinteticos-y-migracion-de-lag" tabindex="-1">15. Casos de aceptación del piloto (Internet con datos sintéticos y migración de LAG) <a class="header-anchor" href="#_15-casos-de-aceptacion-del-piloto-internet-con-datos-sinteticos-y-migracion-de-lag" aria-label="Permalink to &quot;15. Casos de aceptación del piloto (Internet con datos sintéticos y migración de LAG)&quot;">​</a></h2><p>La cooperativa piloto, comercial y de migración, es Laguna Larga (<code>LAG</code>) (DEC-088, que reemplaza a DEC-081). DEC-005 se mantiene: Internet es el primer servicio construido de punta a punta y se valida con datos sintéticos. LAG opera electricidad, gas y prepago, por lo que su primera migración real ocurre después de O7 (PA-MIG-17, opción A) con el prepago disponible (CTR-COB-21, PA-COB-15), y el corte avanza por etapas hasta O11 (DEC-068). Todos los casos se toman de escenarios y criterios existentes en los anexos.</p><h3 id="_15-1-recorrido-internet-con-datos-sinteticos" tabindex="-1">15.1 Recorrido Internet con datos sintéticos <a class="header-anchor" href="#_15-1-recorrido-internet-con-datos-sinteticos" aria-label="Permalink to &quot;15.1 Recorrido Internet con datos sintéticos&quot;">​</a></h3><p>Se ejecutan sobre TEN-001 con datos ficticios; el recorrido completo es el criterio de salida de O6 (DEC-005).</p><table tabindex="0"><thead><tr><th>N.º</th><th>ID de origen</th><th>Anexo</th><th>Precondición</th><th>Acción</th><th>Resultado esperado</th><th>Ola</th></tr></thead><tbody><tr><td>AC-01</td><td>ESC-SRV-INT-01</td><td>T12 parte 1 §1.7</td><td>Ana Demo con factibilidad favorable y oferta INT-100</td><td>Instalación de la ONT-DEMO-0001 y confirmación de activación</td><td>Contrato <code>active</code> con fecha de inicio efectiva; primer comprobante con CAE</td><td>O3–O4</td></tr><tr><td>AC-02</td><td>ESC-SRV-INT-02</td><td>T12 parte 1 §1.7</td><td>Contrato en <code>pendingInstallation</code> con OT cerrada en campo</td><td>El aprovisionamiento responde <code>timeout</code> tres veces</td><td>El contrato no se activa ni se factura; tarea manual para el NOC; el socio ve &quot;activación en curso&quot;</td><td>O3</td></tr><tr><td>AC-03</td><td>ESC-TEC-08 (ESC-03)</td><td>M10 §17</td><td>Orden modificada mientras el técnico estaba sin conexión</td><td>Sincronización al recuperar señal</td><td>Evidencia conservada, conflicto abierto, sin doble movimiento de stock, resolución auditada</td><td>O3</td></tr><tr><td>AC-04</td><td>ESC-TEC-09</td><td>M10 §17</td><td>Lote de mutaciones ya enviado</td><td>El dispositivo reenvía el lote con el mismo <code>clientMutationId</code></td><td>Resultado <code>duplicate</code> sin efectos repetidos</td><td>O3</td></tr><tr><td>AC-05</td><td>ESC-TAR-03</td><td>M04 §17</td><td>Seed de M02 §18 con promoción del piloto</td><td>Cálculo del primer comprobante</td><td>Resultado según el ejemplo de M04 §9.3.9; instalación una sola vez (ver OBS-01)</td><td>O4</td></tr><tr><td>AC-06</td><td><code>ESC-FIS-32</code> (antes &quot;Escenario 32&quot;; CP-FIS-5032)</td><td>M06 §17.4</td><td>Envío de un comprobante a ARCA</td><td>Timeout después de enviar</td><td>Estado <code>uncertain</code>; consulta antes de reintentar; 0 duplicados</td><td>O4</td></tr><tr><td>AC-07</td><td>ESC-COB-R01</td><td>M07 §17.4</td><td>Pago online confirmado por la pasarela</td><td>El webhook llega tres veces</td><td>Un cobro; dos eventos <code>ignored</code></td><td>O5</td></tr><tr><td>AC-08</td><td>ESC-01</td><td>T08 §17.1; M07 §17.6</td><td>Hermano A debe ARS 13.000 y hermano B tiene deuda propia</td><td>A paga ARS 15.000</td><td>13.000 contra A; 2.000 a favor o pendientes; nada se aplica a B</td><td>O5</td></tr><tr><td>AC-09</td><td>ESC-SRV-INT-03</td><td>T12 parte 1 §1.7</td><td>Servicio suspendido en modo <code>restricted</code> por deuda vencida</td><td>Se confirma el pago de la deuda</td><td>Reconexión automática sin cargo; si falla la integración, <code>executionFailed</code> con reintentos y el contrato sigue suspendido</td><td>O6</td></tr><tr><td>AC-10</td><td>ESC-MOR-21</td><td>M08 §17</td><td>Pago confirmado de un servicio suspendido</td><td>La integración remota responde error</td><td>Caso <code>executionFailed</code>, reintentos con backoff y alerta; contrato suspendido hasta el éxito</td><td>O6</td></tr><tr><td>AC-11</td><td>ESC-SRV-INT-04 / ESC-CRM-04</td><td>T12 parte 1; M09 §17</td><td>Titular con deuda ficticia</td><td>Pide la baja por el botón público sin iniciar sesión</td><td>Código en menos de 24 h; no se exige pago ni se crea cargo; OT de retiro de la ONT; la deuda sigue en M07</td><td>O6</td></tr><tr><td>AC-12</td><td>ESC-SRV-INT-05</td><td>T12 parte 1 §1.7</td><td>Ana con INT-100 en ciclo mensual</td><td>Pide cambio a INT-300 a mitad de mes</td><td>Cambio con vigencia desde el ciclo siguiente; cada mes se factura con su plan</td><td>O6</td></tr><tr><td>AC-13</td><td>ESC-SRV-INT-06</td><td>T12 parte 1 §1.7</td><td>Operador de TEN-002 con permiso de ver contratos</td><td>Consulta por ID el contrato y la ONT de TEN-001</td><td>404 sin revelar existencia; los jobs de TEN-002 no leen comandos de TEN-001</td><td>O2–O6</td></tr><tr><td>AC-14</td><td>ESC-SRV-INT-07</td><td>T12 parte 1 §1.7</td><td>Hermano A con deuda en el domicilio compartido</td><td>Hermano B solicita Internet en el mismo domicilio</td><td>Se advierte la deuda sin bloquear ni trasladarla; contrato de B independiente</td><td>O2</td></tr><tr><td>AC-15</td><td>ESC-04</td><td>T08 §17.1</td><td>Emisión fiscal y pago confirmados después del punto de restauración</td><td>Restauración selectiva del tenant</td><td>Se concilian identificadores externos; 0 emisiones o cobros duplicados</td><td>O4–O5</td></tr></tbody></table><h3 id="_15-2-migracion-de-lag-servicios-medidos-prepago-y-entes-recaudadores" tabindex="-1">15.2 Migración de LAG: servicios medidos, prepago y entes recaudadores <a class="header-anchor" href="#_15-2-migracion-de-lag-servicios-medidos-prepago-y-entes-recaudadores" aria-label="Permalink to &quot;15.2 Migración de LAG: servicios medidos, prepago y entes recaudadores&quot;">​</a></h3><p>Se ejecutan después de O7 con la configuración de LAG (nunca datos personales de su base relevada; DEC-088). En los ensayos (etapa E0) se usa la copia seudonimizada de forma irreversible (PA-MIG-15; RF-MIG-095); en el paralelo (etapa E1), el tenant de LAG con el delta diario desde ProCoop. Los ejecutan los usuarios clave de LAG junto con el equipo de migración, y su aprobación integra el criterio de go/no-go del corte comercial (<code>08-plan-puesta-en-marcha.md</code>, GO-02 y GO-25 a GO-27).</p><table tabindex="0"><thead><tr><th>N.º</th><th>ID de origen</th><th>Anexo</th><th>Precondición</th><th>Acción</th><th>Resultado esperado</th><th>Ola y etapa</th></tr></thead><tbody><tr><td>AC-16</td><td>ESC-MED-22</td><td>M03 §17</td><td>Medidor prepago de LAG con su sistema de prepago configurado; venta prepaga cobrada en caja o portal (RF-COB-075)</td><td>El proveedor de prepago falla al pedir el crédito o token</td><td>La recarga queda en la bandeja; el reintento no genera un segundo token; la devolución, si se decide, la hace M07</td><td>O7; E0 y E1</td></tr><tr><td>AC-17</td><td>ESC-TAR-38</td><td>M04 §17</td><td>Consumo de gas medido entregado por M03 y factor del período cargado (valores ficticios del escenario)</td><td>Cálculo del comprobante de gas</td><td>Volumen corregido según RN-TAR-035 con traza de medido, factores y resultado; sin factor del período, la cuenta se excluye con <code>TAR-E-GAS-FACTOR</code> y el lote continúa</td><td>O7; E0 y E1</td></tr><tr><td>AC-18</td><td>ESC-COB-L01</td><td>M07 §17.6</td><td>Formato de rendición Red Link de LAG configurado en el perfil del conector</td><td>Importación de una línea con identificador de 10 dígitos, servicio 02 y concepto 002</td><td>La línea se resuelve a la cuenta y al servicio de gas correctos; ante dos obligaciones impagas con el mismo importe no elige la más reciente (ESC-COB-L02)</td><td>O7; E0 y E1</td></tr><tr><td>AC-19</td><td>ESC-COB-L04</td><td>M07 §17.6</td><td>Rama SIRO de LAG configurada</td><td>Emisión de una factura de ARS 100.000 o más</td><td>Error informado y uso del formato extendido o QR; nunca un código de barras vacío (PA-COB-16)</td><td>O7; E0 y E1</td></tr><tr><td>AC-20</td><td>ESC-COB-L05</td><td>M07 §17.6</td><td>Paralelo de LAG en curso con electricidad, gas y prepago</td><td>Comparación ProCoop contra GoodApps de un ciclo completo</td><td>Suma de cobranza por día y saldos por cuenta iguales, con tolerancia 0; el paralelo se aprueba con 2 ciclos consecutivos, 0 diferencias sin explicar y emparejamiento ≥ 99,9 % (T07 §17.4; PRM-MIG-041, PRM-MIG-042)</td><td>Después de O7; E1</td></tr></tbody></table><hr><h2 id="_16-puntos-a-definir-y-observaciones-sobre-las-fuentes" tabindex="-1">16. Puntos a definir y observaciones sobre las fuentes <a class="header-anchor" href="#_16-puntos-a-definir-y-observaciones-sobre-las-fuentes" aria-label="Permalink to &quot;16. Puntos a definir y observaciones sobre las fuentes&quot;">​</a></h2><h3 id="_16-1-puntos-a-definir" tabindex="-1">16.1 Puntos a definir <a class="header-anchor" href="#_16-1-puntos-a-definir" aria-label="Permalink to &quot;16.1 Puntos a definir&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Punto</th><th>Situación en las fuentes</th></tr></thead><tbody><tr><td>AD-01</td><td>Plazos de corrección de defectos por severidad (salvo vulnerabilidades y pruebas inestables)</td><td>No definidos</td></tr><tr><td>AD-02</td><td>Herramienta de registro y seguimiento de defectos</td><td>No definida</td></tr><tr><td>AD-03</td><td>Asignación nominal de personas a los roles de prueba, incluidos los usuarios clave de LAG</td><td>La piloto es LAG (DEC-088); las personas no están designadas</td></tr><tr><td>AD-04</td><td>Cantidad de usuarios clave, calendario y duración de la aceptación de usuario</td><td>No definidos; las olas no tienen fechas (DEC-006)</td></tr><tr><td>AD-05</td><td>Proveedor y alcance de la prueba de penetración externa</td><td>Momento definido (RNF-NFR-095, PA-NFR-17); proveedor no definido</td></tr><tr><td>AD-06</td><td>Dispositivos reales de referencia para pruebas manuales por ola</td><td>Perfil mínimo definido (RNF-NFR-183, RNF-NFR-185; PA-NFR-13); modelos concretos no definidos</td></tr><tr><td>AD-07</td><td>Recalibración del perfil de carga con mediciones de la piloto</td><td>Prevista (AGR-020); valores posteriores no definidos</td></tr><tr><td>AD-08</td><td>Plantilla del acta de aceptación de usuario por ola</td><td>Prevista para el corte (RF-MIG-087); formato no definido</td></tr></tbody></table><h3 id="_16-2-observaciones-sobre-las-fuentes-para-validar-no-se-modificaron" tabindex="-1">16.2 Observaciones sobre las fuentes (para validar; no se modificaron) <a class="header-anchor" href="#_16-2-observaciones-sobre-las-fuentes-para-validar-no-se-modificaron" aria-label="Permalink to &quot;16.2 Observaciones sobre las fuentes (para validar; no se modificaron)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Observación</th><th>Fuentes</th></tr></thead><tbody><tr><td>OBS-01</td><td>Los valores del primer comprobante del piloto difieren entre ESC-SRV-INT-01 (abono ARS 25.000, instalación ARS 30.000, promoción 10 %, total ARS 60.000) y ESC-TAR-03 (abono ARS 15.000, instalación ARS 20.000, promoción 50 %, total ARS 30.000). HUE-SRV-05 alineó M02 §18, M19 y M04 con un único seed, pero T12 parte 1 conserva los valores anteriores. Los casos AC-01 y AC-05 deben usar un solo conjunto dorado</td><td>T12 parte 1 §1.7; M04 §17; <code>05-registro-huecos.md</code> (HUE-SRV-05)</td></tr><tr><td>OBS-02</td><td>RNF-NFR-170 enumera 5 ambientes; T01 §7.10 define 7 (agrega <code>dev</code> y <code>sandbox</code>). Este documento sigue T01, a la que RNF-NFR-170 remite como detalle</td><td>T08 §12.2; T01 §7.10</td></tr><tr><td>OBS-03</td><td>El marcado y dominio de los datos ficticios difieren: T08 usa <code>isFictitious</code> y <code>@ejemplo.test</code>; el plan <code>03</code> R13 usa <code>isDemo: true</code> y <code>@example.com</code></td><td>RNF-NFR-160; <code>03</code> R13</td></tr><tr><td>OBS-04</td><td>T07 §9.6 punto 9 remite a &quot;§17.6&quot; para el criterio de aprobación del paralelo; el criterio está en T07 §17.4</td><td>T07 §9.6, §17.4</td></tr><tr><td>OBS-05</td><td>El plan <code>03</code> §9.8 describe ESC-SRV-INT-02 y ESC-SRV-INT-03 como &quot;pago online y presencial&quot;, pero en T12 parte 1 §1.7 esos IDs son la falla de aprovisionamiento y la reconexión tras el pago. Los casos de pago de O5 se toman de M07 §17 (por ejemplo ESC-COB-R01 y ESC-01)</td><td><code>03</code> §9.8; T12 parte 1 §1.7</td></tr></tbody></table>',23))])}const y=c(p,[["render",m]]);export{f as __pageData,y as default};
